// Verify X-COREI-Signature = sha256=HMAC_SHA256(secret, timestamp + '.' + rawBody)
// Store the signing secret as the n8n environment variable COREI_WEBHOOK_SECRET (never inside the workflow).
const crypto = require('crypto');
const out = [];
for (const item of $input.all()) {
  const h = item.json.headers; const ts = h['x-corei-timestamp'];
  const raw = item.binary?.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body);
  const want = 'sha256=' + crypto.createHmac('sha256', $env.COREI_WEBHOOK_SECRET).update(ts + '.' + raw).digest('hex');
  const fresh = Math.abs(Date.now() / 1000 - Number(ts)) < 300;
  if (!fresh || want !== h['x-corei-signature']) throw new Error('COREI webhook signature check failed');
  out.push({ json: { event: h['x-corei-event'], event_id: h['x-corei-event-id'], body: JSON.parse(raw) } });
}
return out;
